@Component @Primary
public class ExecutionTimeService implements StudentService {
    private LoggingDecorator loggingDecorator;   // injected
    public void createStudent(Student student) {
        long start = System.currentTimeMillis();
        loggingDecorator.createStudent(student);
        long end = System.currentTimeMillis();
        System.out.println(end - start);
    }
}

@Component
public class LoggingDecorator implements StudentService {
    private StudentServiceImpl studentServiceimpl; // injected
    public void createStudent(Student student) {
        LoggingServiceUtil.logStart("StudentServiceImpl", "createStudent"); // prints "Executing -> StudentServiceImpl : createStudent"
        studentServiceimpl.createStudent(student);                   // repository prints "Student saved"
        LoggingServiceUtil.logEnd("StudentServiceImpl", "createStudent");   // prints "Finishing -> StudentServiceImpl : createStudent"
    }
}

public interface StudentService { void createStudent(Student s); }

