interface StudentOperations {
    String createStudent(String name);
}

class LoggingStudentService implements StudentOperations {
    private final StudentOperations target;
    LoggingStudentService(StudentOperations target) { this.target = target; }

    public String createStudent(String name) {
        System.out.println("Method started");
        try {
            return target.createStudent(name);
        } finally {
            System.out.println("Method finished");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        StudentOperations real = name -> { throw new IllegalStateException("DB down"); };
        StudentOperations ops = new LoggingStudentService(real);
        try {
            System.out.println(ops.createStudent("Aditya"));
            System.out.println("Saved");
        } catch (IllegalStateException e) {
            System.out.println("Caught: " + e.getMessage());
        }
    }
}
